function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function todayISO(){const d=new Date();const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
function login(){const code=document.getElementById('code').value.trim();const v=data().vendors.find(x=>String(x.code||'').toUpperCase()===code.toUpperCase());if(!v){alert('접근코드가 올바르지 않습니다.');return}sessionStorage.setItem('vendorId',String(v.id));show(v)}
function loginBox(showLogin){document.getElementById('login').classList.toggle('hidden',!showLogin);document.getElementById('requests').classList.toggle('hidden',showLogin);document.getElementById('logoutBtn').classList.toggle('hidden',showLogin)}
function show(v){loginBox(false);document.getElementById('title').textContent=v.name+' 신청내역';document.getElementById('vendorInfo').textContent='담당자 '+(v.contact||'-')+' · '+(v.phone||'-')+' · '+(v.email||'-');render(v)}
function requestGroupKey(r){if(r.batchId)return 'batch:'+r.batchId;return ['group',r.vendorId||'',r.office||'',r.applicant||'',r.date1||'',r.date2||''].join('|')}
function groupRequests(rows){const map=new Map();rows.forEach(r=>{const key=requestGroupKey(r);if(!map.has(key))map.set(key,[]);map.get(key).push(r)});return [...map.entries()].map(([key,rs])=>{rs.sort((a,b)=>(new Date(b.updatedAt||b.createdAt||0).getTime()||Number(b.id)||0)-(new Date(a.updatedAt||a.createdAt||0).getTime()||Number(a.id)||0));const first=rs[0];const confirmed=rs.find(r=>r.confirmedDate);const rejected=rs.find(r=>r.status==='일정 불가');const status=confirmed?'일정 확정':rejected?'일정 불가':rs.some(r=>r.status==='일정 협의 필요')?'일정 협의 필요':'업체 회신 대기';const memo=[...new Set(rs.map(r=>String(r.memo||'').trim()).filter(Boolean))].join(' / ');const rejectionReason=[...new Set(rs.map(r=>String(r.rejectionReason||'').trim()).filter(Boolean))].join(' / ');const histMap=new Map();rs.forEach(r=>(r.history||[]).forEach(h=>{const k=[h.at,h.status,h.detail,h.actor].join('|');if(!histMap.has(k))histMap.set(k,h)}));const history=[...histMap.values()].sort((a,b)=>String(b.at).localeCompare(String(a.at)));return {key,main:first,rows:rs,groupIds:rs.map(r=>r.id),status,confirmedDate:confirmed?.confirmedDate||'',date1:(confirmed||first).date1||'',date2:(confirmed||first).date2||'',memo,rejectionReason,history}})}
function matches(g){const sf=document.getElementById('statusFilter')?.value||'';const cf=document.getElementById('confirmedFilter')?.value||'';if(sf && g.status!==sf)return false;if(cf && g.confirmedDate!==cf)return false;return true}
function sorted(arr){const mode=document.getElementById('sortFilter')?.value||'newest';return arr.sort((a,b)=>{if(mode==='confirmed'){const ad=a.confirmedDate||'9999-12-31',bd=b.confirmedDate||'9999-12-31';return ad.localeCompare(bd)||((new Date(b.main.createdAt||0).getTime()||0)-(new Date(a.main.createdAt||0).getTime()||0))}const at=new Date(a.main.createdAt||0).getTime()||Number(a.main.id)||0,bt=new Date(b.main.createdAt||0).getTime()||Number(b.main.id)||0;return mode==='oldest'?at-bt:bt-at})}
function renderSummary(arr,all){const confirmed=all.filter(g=>g.status==='일정 확정').length,waiting=all.filter(g=>g.status==='업체 회신 대기').length,agreement=all.filter(g=>g.status==='일정 협의 필요').length,rejected=all.filter(g=>g.status==='일정 불가').length;document.getElementById('summary').innerHTML='<span class="summary-pill">전체 '+all.length+'건</span><span class="summary-pill">표시 '+arr.length+'건</span><span class="summary-pill">일정 확정 '+confirmed+'건</span><span class="summary-pill">회신 대기 '+waiting+'건</span><span class="summary-pill">일정 협의 '+agreement+'건</span><span class="summary-pill">일정 불가 '+rejected+'건</span>'}
function historyMessage(h){const s=String(h.status||'변경');const d=String(h.detail||'');const actor=String(h.actor||'');let msg='';if(s==='신청 접수'){msg='설명 일정 <strong>신청이 접수</strong>되었습니다.'}else if(s==='신청내용 수정'){msg='<strong>신청내용이 수정</strong>되었습니다.'}else if(s==='일정 불가'){const m=d.match(/사유:\s*(.*)$/);msg='<strong>일정 불가</strong> 처리되었습니다.';if(m&&m[1])msg+=' 사유: '+esc(m[1])}else if(s==='일정 불가 사유 수정'){const m=d.match(/사유를 수정했습니다:\s*(.*)$/);msg='<strong>일정 불가 사유가 수정</strong>되었습니다.';if(m&&m[1])msg+=' 사유: '+esc(m[1])}else if(s==='업체 회신 대기'){msg='업체가 <strong>다시 일정 회신</strong>으로 변경했습니다.'}else if(s==='일정 협의 필요'){msg='업체가 <strong>일정 협의</strong>를 요청했습니다.'}else if(s==='일정 확정'){const m=d.match(/(\d{4}-\d{2}-\d{2})/);msg=m?'업체가 <strong>'+esc(m[1])+' 일정으로 확정</strong>했습니다.':'업체가 <strong>일정 확정</strong>했습니다.'}else if(s==='확정 일정 변경'){const m=d.match(/(\d{4}-\d{2}-\d{2})에서 (\d{4}-\d{2}-\d{2})로/);msg=m?'업체가 <strong>확정 일정을 '+esc(m[1])+' → '+esc(m[2])+'로 변경</strong>했습니다.':'업체가 <strong>확정 일정</strong>을 변경했습니다.'}else{msg='<strong>'+esc(s)+'</strong> 처리되었습니다.'}return msg+' <span class="muted">('+esc(actor)+')</span>'}
function historyHtml(history){if(!history?.length)return '';return '<details class="history-box"><summary>상태 변경 이력 · '+history.length+'건</summary><ul class="history-list">'+history.map(h=>'<li class="history-item"><span class="history-time">'+esc(new Date(h.at).toLocaleString('ko-KR'))+'</span><span class="history-message">'+historyMessage(h)+'</span></li>').join('')+'</ul></details>'}
function equipmentText(ids,eq){const seen=new Set();const items=ids.map(id=>eq[id]).filter(Boolean).filter(e=>{if(seen.has(e.id))return false;seen.add(e.id);return true});if(!items.length)return '<div class=\"equipment-list-box\"><div class=\"equipment-list-title\">신청 장비</div><div class=\"equipment-item\">장비 정보를 확인할 수 없습니다.</div></div>';return '<div class=\"equipment-list-box\"><div class=\"equipment-list-title\">신청 장비 · '+items.length+'개</div><div class=\"equipment-list\">'+items.map(e=>'<div class=\"equipment-item\"><b>'+esc(e.name)+'</b> <span>('+esc(e.model||'-')+' / '+esc(e.company||'-')+')</span></div>').join('')+'</div></div>'}
function render(v){const d=data();const eq=Object.fromEntries(d.equipment.map(e=>[e.id,e]));const all=groupRequests(d.requests.filter(r=>Number(r.vendorId)===Number(v.id)));const arr=sorted(all.filter(matches));document.getElementById('count').textContent=arr.length+'건';renderSummary(arr,all);document.getElementById('list').innerHTML=arr.length?arr.map(g=>{const r=g.main;const ids=[...new Set(g.rows.map(x=>x.equipmentId).filter(Boolean))];let actions='';if(g.status==='업체 회신 대기')actions=actionButtons(g);else if(g.status==='일정 협의 필요')actions=agreementBox(g);const confirmed=g.confirmedDate?confirmedBox(g):'';const rejected=g.status==='일정 불가'?rejectedBox(g):'';const changed=(g.history||[]).some(h=>h.status==='확정 일정 변경');const cls=g.status==='일정 확정'?'is-confirmed':g.status==='일정 협의 필요'?'is-agreement':g.status==='일정 불가'?'is-rejected':'is-waiting';return '<div class="card '+cls+'"><div class="card-head"><div><div class="eyebrow">설명 신청 · '+esc((r.createdAt||'').slice(0,10))+'</div><h3 class="equipment-title">'+esc(r.office||'-')+' · '+ids.length+'개 장비</h3></div><span class="status">'+esc(g.status)+(changed?' <span class="change-badge">확정 일정 변경</span>':'')+'</span></div>'+equipmentText(ids,eq)+'<div class="info-grid"><div><span>사업소</span><b>'+esc(r.office||'-')+'</b></div><div><span>신청자</span><b>'+esc(r.applicant||'-')+'</b></div><div><span>회사 연락처</span><b>'+esc(r.extension||'-')+'</b></div><div><span>이메일</span><b>'+esc(r.email||'-')+'</b></div><div><span>희망일 1</span><b>'+esc(g.date1||'-')+'</b></div><div><span>희망일 2</span><b>'+esc(g.date2||'-')+'</b></div></div>'+(g.memo?'<div class="request-box"><span>추가 요청사항</span><p>'+esc(g.memo)+'</p></div>':'')+confirmed+rejected+actions+historyHtml(g.history)+'</div>'}).join(''):'<div class="notice">조건에 맞는 신청내역이 없습니다. 필터를 변경해 보세요.</div>'}
function decisionControls(g,includeAgreement=true){const ids=JSON.stringify(g.groupIds);return `<div class="decision-title">일정 회신</div><div class="decision-help">가능한 희망일이 있으면 해당 날짜에 동의해 주세요. 두 날짜 모두 어려우면 일정 협의를 선택하거나 일정 불가를 선택할 수 있습니다.</div><div class="decision-actions"><button type="button" class="btn primary" data-action="confirm1" data-ids='${esc(ids)}'>희망일 1 동의</button><button type="button" class="btn primary" data-action="confirm2" data-ids='${esc(ids)}'>희망일 2 동의</button>${includeAgreement?`<button type="button" class="btn secondary" data-action="agreement" data-ids='${esc(ids)}'>일정 협의</button>`:''}</div><div class="reject-area"><div class="reject-label">일정 불가</div><div class="small-note" style="margin-bottom:7px">일정 진행이 어려운 경우 선택하세요. 사유 입력은 선택사항입니다.</div><textarea id="reject-reason-${g.main.id}" placeholder="일정이 어려운 사유를 입력해주세요. 입력하지 않아도 됩니다."></textarea><div class="reject-actions"><button type="button" class="btn danger" data-action="reject" data-ids='${esc(ids)}' data-reason-id="reject-reason-${g.main.id}">일정 불가로 변경</button></div></div>`}
function actionButtons(g){return `<div class="decision-panel">${decisionControls(g,true)}</div>`}
function agreementBox(g){const ids=JSON.stringify(g.groupIds);return `<div class="decision-panel agreement"><div class="decision-title">일정 협의</div><div class="decision-help">사업소 담당자와 일정을 협의한 후 날짜를 등록하세요. 아래에서 희망일 동의로 변경하거나 일정 불가로 변경할 수도 있습니다.</div><div class="field"><label>협의 일정</label><input id="agree-${g.main.id}" type="date" min="${todayISO()}" onclick="this.showPicker&&this.showPicker()"></div><div class="actions"><button type="button" class="btn primary" data-action="register" data-id="${g.main.id}">협의 일정 등록</button><button type="button" class="btn secondary" data-action="back" data-ids='${esc(ids)}'>회신 화면으로 돌아가기</button></div><div class="decision-subsection" style="margin-top:16px;padding-top:14px;border-top:1px solid #dfe6eb">${decisionControls(g,false)}</div></div>`}
function confirmedBox(g){const id=g.main.id;const ids=JSON.stringify(g.groupIds);return `<div class="confirmed"><div><span>확정 일정</span><b style="display:block;margin-top:4px">${esc(g.confirmedDate)}</b></div><div class="actions"><button type="button" class="btn secondary small" data-action="editConfirmed" data-id="${id}">확정 일정 수정</button></div></div><div id="edit-confirmed-${id}" class="decision-panel hidden"><div class="decision-title">확정 일정 수정</div><div class="decision-help">확정된 날짜를 변경하거나, 업체 사정으로 일정이 어려워진 경우 일정 불가로 변경할 수 있습니다.</div><div class="field"><label>변경할 확정 일정</label><input id="confirmed-edit-${id}" type="date" value="${esc(g.confirmedDate)}" min="${todayISO()}" onclick="this.showPicker&&this.showPicker()"></div><div class="actions"><button type="button" class="btn primary" data-action="saveConfirmedEdit" data-id="${id}">수정 저장</button><button type="button" class="btn secondary" data-action="cancelConfirmedEdit" data-id="${id}">취소</button></div><div class="reject-area"><div class="reject-label">일정 불가로 변경</div><div class="small-note" style="margin-bottom:7px">확정 후 일정이 어려워진 경우 선택하세요. 사유 입력은 선택사항입니다.</div><textarea id="reject-confirmed-${id}" placeholder="일정이 어려운 사유를 입력해주세요. 입력하지 않아도 됩니다."></textarea><div class="reject-actions"><button type="button" class="btn danger" data-action="reject" data-ids='${esc(ids)}' data-reason-id="reject-confirmed-${id}">일정 불가로 변경</button></div></div></div>`}
function rejectedBox(g){const ids=JSON.stringify(g.groupIds);return `<div class="request-box" style="background:#fff3f3;border-left-color:#c65353"><span>업체 일정 불가 사유</span><p>${esc(g.rejectionReason||'사유가 입력되지 않았습니다.')}</p></div><div class="decision-panel"><div class="decision-title">일정 불가 수정</div><div class="decision-help">일정이 가능해졌다면 다시 일정 회신할 수 있습니다. 사유도 수정하거나 비울 수 있습니다.</div><div class="field"><label>일정 불가 사유 <span class="muted">(선택)</span></label><textarea id="reject-edit-${g.main.id}" placeholder="일정이 어려운 사유를 입력해주세요. 입력하지 않아도 됩니다.">${esc(g.rejectionReason||'')}</textarea></div><div class="actions"><button type="button" class="btn primary" data-action="resumeReply" data-ids='${esc(ids)}'>다시 일정 회신</button><button type="button" class="btn danger" data-action="saveRejectReason" data-ids='${esc(ids)}' data-reason-id="reject-edit-${g.main.id}">불가 사유 수정</button></div></div>`}
function rejectGroup(ids,reasonId){const text=(document.getElementById(reasonId)?.value||'').trim();updateGroup(ids,rows=>{rows.forEach(r=>{r.status='일정 불가';r.confirmedDate='';r.rejectionReason=text});addHistory(rows,'일정 불가',text?'업체가 일정 불가 처리했습니다. 사유: '+text:'업체가 일정 불가 처리했습니다.')})}
function resumeReplyGroup(ids){updateGroup(ids,rows=>{rows.forEach(r=>{r.status='업체 회신 대기';r.confirmedDate='';r.rejectionReason='' });addHistory(rows,'업체 회신 대기','업체가 일정 불가 상태에서 다시 일정 회신으로 변경했습니다.')})}
function saveRejectReason(ids,reasonId){const text=(document.getElementById(reasonId)?.value||'').trim();updateGroup(ids,rows=>{rows.forEach(r=>{r.status='일정 불가';r.confirmedDate='';r.rejectionReason=text});addHistory(rows,'일정 불가 사유 수정',text?'일정 불가 사유를 수정했습니다: '+text:'일정 불가 사유를 비웠습니다.')})}
function saveConfirmedEdit(id){const el=document.getElementById('confirmed-edit-'+id);const date=el?.value||'';if(!date){alert('변경할 확정 날짜를 입력해주세요.');return}if(date<todayISO()){alert('확정일은 오늘 이전 날짜로 선택할 수 없습니다.');return}const g=getGroupByIds([id]);if(!g)return;const oldDate=g.confirmedDate||'';if(oldDate===date){alert('기존 확정일과 같은 날짜입니다.');return}updateGroup(g.groupIds,rows=>{rows.forEach(r=>{r.status='일정 확정';r.confirmedDate=date;r.rejectionReason=''});addHistory(rows,'확정 일정 변경','확정 일정이 '+oldDate+'에서 '+date+'로 변경되었습니다.')})}
function renderCurrent(){const v=current();if(v)render(v)}
function current(){const d=data();const id=Number(sessionStorage.getItem('vendorId'));return d.vendors.find(v=>Number(v.id)===id)}
function updateGroup(ids,fn){const d=data();const set=new Set(ids.map(Number));const rows=d.requests.filter(r=>set.has(Number(r.id)));if(!rows.length){alert('신청내역을 찾을 수 없습니다.');return}fn(rows);save(d);const v=current();if(v)render(v)}
function addHistory(rows,status,detail,actor='업체'){const now=new Date().toISOString();rows.forEach(r=>{if(!Array.isArray(r.history))r.history=[];r.history.push({at:now,status,detail,actor});r.updatedAt=now})}
function confirmGroup(ids,date){if(!date){alert('확정할 날짜가 없습니다.');return}if(date<todayISO()){alert('확정일은 오늘 이전 날짜로 선택할 수 없습니다.');return}updateGroup(ids,rows=>{const wasConfirmed=rows.some(r=>r.confirmedDate);const oldDate=rows.find(r=>r.confirmedDate)?.confirmedDate||'';rows.forEach(r=>{r.status='일정 확정';r.confirmedDate=date;r.rejectionReason=''});addHistory(rows,wasConfirmed?'확정 일정 변경':'일정 확정',wasConfirmed?'확정 일정이 '+oldDate+'에서 '+date+'로 변경되었습니다.':'업체가 '+date+'로 일정을 확정했습니다.')})}
function needAgreementGroup(ids){updateGroup(ids,rows=>{rows.forEach(r=>{r.status='일정 협의 필요';r.confirmedDate=''});addHistory(rows,'일정 협의 필요','업체가 희망일 대신 일정 협의를 요청했습니다.')})}
function backToReplyGroup(ids){updateGroup(ids,rows=>{rows.forEach(r=>{r.status='업체 회신 대기';r.confirmedDate=''});addHistory(rows,'업체 회신 대기','업체가 일정 협의 상태에서 회신 화면으로 돌아갔습니다.')})}
function registerAgreementGroup(id){const el=document.getElementById('agree-'+id);const date=el?.value||'';if(!date){alert('협의된 날짜를 입력해주세요.');return}if(date<todayISO()){alert('협의 일정은 오늘 이전 날짜로 선택할 수 없습니다.');return}const d=data();const r=d.requests.find(x=>Number(x.id)===Number(id));if(!r){alert('신청내역을 찾을 수 없습니다.');return}const key=requestGroupKey(r);const ids=d.requests.filter(x=>requestGroupKey(x)===key).map(x=>x.id);confirmGroup(ids,date)}
document.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b)return;const action=b.dataset.action;try{const ids=JSON.parse(b.dataset.ids||'[]');if(action==='confirm1'||action==='confirm2'){const g=getGroupByIds(ids);confirmGroup(ids,action==='confirm1'?g.date1:g.date2)}else if(action==='reject'){rejectGroup(ids,b.dataset.reasonId)}else if(action==='resumeReply'){resumeReplyGroup(ids)}else if(action==='saveRejectReason'){saveRejectReason(ids,b.dataset.reasonId)}else if(action==='editConfirmed'){document.getElementById('edit-confirmed-'+b.dataset.id)?.classList.remove('hidden')}else if(action==='cancelConfirmedEdit'){document.getElementById('edit-confirmed-'+b.dataset.id)?.classList.add('hidden')}else if(action==='saveConfirmedEdit'){saveConfirmedEdit(b.dataset.id)}else if(action==='agreement'){needAgreementGroup(ids)}else if(action==='register'){registerAgreementGroup(b.dataset.id)}else if(action==='back'){backToReplyGroup(ids)}}catch(err){console.error(err);alert('처리 중 오류가 발생했습니다. 페이지를 새로고침한 뒤 다시 시도해주세요.')}})
function getGroupByIds(ids){const d=data();const set=new Set(ids.map(Number));const rows=d.requests.filter(r=>set.has(Number(r.id)));const confirmed=rows.find(r=>r.confirmedDate);const source=confirmed||rows[0]||{};return{date1:source.date1||'',date2:source.date2||'',groupIds:rows.map(r=>r.id),main:source}}
function logout(){sessionStorage.removeItem('vendorId');location.reload()}
document.getElementById('code').addEventListener('keydown',e=>{if(e.key==='Enter')login()});
window.kescoAfterInit=function(){const v=current();if(v)show(v);else loginBox(true);};
kescoInit();
